/* eslint-disable stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setNonEnumerableReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' ); // eslint-disable-line id-length
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var EncodingSet = require( '@stdlib/plot/vega/mark/base/encoding-set' );
var format = require( '@stdlib/string/format' );
var properties = require( './properties.json' );

// Note: keep the following in alphabetical order according to the `require` path...
var getCornerRadius = require( './corner-radius/get.js' );
var setCornerRadius = require( './corner-radius/set.js' );

var getCornerRadiusBottomLeft = require( './corner-radius-bottom-left/get.js' );
var setCornerRadiusBottomLeft = require( './corner-radius-bottom-left/set.js' );

var getCornerRadiusBottomRight = require( './corner-radius-bottom-right/get.js' ); // eslint-disable-line id-length
var setCornerRadiusBottomRight = require( './corner-radius-bottom-right/set.js' ); // eslint-disable-line id-length

var getCornerRadiusTopLeft = require( './corner-radius-top-left/get.js' );
var setCornerRadiusTopLeft = require( './corner-radius-top-left/set.js' );

var getCornerRadiusTopRight = require( './corner-radius-top-right/get.js' );
var setCornerRadiusTopRight = require( './corner-radius-top-right/set.js' );

var getProperties = require( './properties/get.js' );


// VARIABLES //

var debug = logger( 'vega:mark:rect:encoding-set:main' );


// MAIN //

/**
* Rect mark encoding set constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {Value} [options.aria] - flag indicating whether to include ARIA attributes in SVG output
* @param {Value} [options.blend] - color blend mode
* @param {Value} [options.cornerRadius] - corner radius (in pixels) for all four corners
* @param {Value} [options.cornerRadiusBottomLeft] - corner radius (in pixels) for the bottom left corner
* @param {Value} [options.cornerRadiusBottomRight] - corner radius (in pixels) for the bottom right corner
* @param {Value} [options.cornerRadiusTopLeft] - corner radius (in pixels) for the top left corner
* @param {Value} [options.cornerRadiusTopRight] - corner radius (in pixels) for the top right corner
* @param {Value} [options.cursor] - mouse cursor used over a mark
* @param {Value} [options.description] - text description of a mark item for ARIA accessibility
* @param {Value} [options.fill] - fill color
* @param {Value} [options.fillOpacity] - fill opacity
* @param {Value} [options.height] - mark height
* @param {Value} [options.href] - URL to load upon mouse click
* @param {Value} [options.opacity] - mark opacity
* @param {Value} [options.stroke] - stroke color
* @param {Value} [options.strokeCap] - stroke cap for line ending style
* @param {Value} [options.strokeDash] - stroke dash
* @param {Value} [options.strokeDashOffset] - pixel offset at which to start the dash array
* @param {Value} [options.strokeJoin] - stroke line join method
* @param {Value} [options.strokeMiterLimit] - miter limit at which to bevel a line join
* @param {Value} [options.strokeOpacity] - stroke opacity
* @param {Value} [options.strokeWidth] - stroke width
* @param {Value} [options.tooltip] - tooltip text to show upon mouse hover
* @param {Value} [options.width] - mark width
* @param {Value} [options.x] - primary x-coordinate
* @param {Value} [options.x2] - secondary x-coordinate
* @param {Value} [options.xc] - center x-coordinate
* @param {Value} [options.y] - primary y-coordinate
* @param {Value} [options.y2] - secondary y-coordinate
* @param {Value} [options.yc] - center y-coordinate
* @param {Value} [options.zindex] - layering order of sibling mark items
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {RectEncodingSet} encoding set instance
*
* @example
* var encoding = new RectEncodingSet();
* // returns <RectEncodingSet>
*/
function RectEncodingSet( options ) {
	var nargs;
	var v;
	var k;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof RectEncodingSet ) ) {
		if ( nargs === 0 ) {
			return new RectEncodingSet();
		}
		return new RectEncodingSet( options );
	}
	EncodingSet.call( this );
	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < properties.length; i++ ) {
			k = properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	return this;
}

/*
* Inherit from the `EncodingSet` prototype.
*/
inherit( RectEncodingSet, EncodingSet );

/**
* Constructor name.
*
* @private
* @name name
* @memberof RectEncodingSet
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( RectEncodingSet, 'name', 'RectEncodingSet' );

/**
* Encoding specifying the corner radius (in pixels) for all four corners.
*
* @name cornerRadius
* @memberof RectEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new RectEncodingSet({
*     'cornerRadius': new Value({
*         'value': 5
*     })
* });
*
* var v = encoding.cornerRadius;
* // returns <Value>
*/
setReadWriteAccessor( RectEncodingSet.prototype, 'cornerRadius', getCornerRadius, setCornerRadius );

/**
* Encoding specifying the corner radius (in pixels) for the bottom left corner.
*
* @name cornerRadiusBottomLeft
* @memberof RectEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new RectEncodingSet({
*     'cornerRadiusBottomLeft': new Value({
*         'value': 5
*     })
* });
*
* var v = encoding.cornerRadiusBottomLeft;
* // returns <Value>
*/
setReadWriteAccessor( RectEncodingSet.prototype, 'cornerRadiusBottomLeft', getCornerRadiusBottomLeft, setCornerRadiusBottomLeft );

/**
* Encoding specifying the corner radius (in pixels) for the bottom right corner.
*
* @name cornerRadiusBottomRight
* @memberof RectEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new RectEncodingSet({
*     'cornerRadiusBottomRight': new Value({
*         'value': 5
*     })
* });
*
* var v = encoding.cornerRadiusBottomRight;
* // returns <Value>
*/
setReadWriteAccessor( RectEncodingSet.prototype, 'cornerRadiusBottomRight', getCornerRadiusBottomRight, setCornerRadiusBottomRight );

/**
* Encoding specifying the corner radius (in pixels) for the top left corner.
*
* @name cornerRadiusTopLeft
* @memberof RectEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new RectEncodingSet({
*     'cornerRadiusTopLeft': new Value({
*         'value': 5
*     })
* });
*
* var v = encoding.cornerRadiusTopLeft;
* // returns <Value>
*/
setReadWriteAccessor( RectEncodingSet.prototype, 'cornerRadiusTopLeft', getCornerRadiusTopLeft, setCornerRadiusTopLeft );

/**
* Encoding specifying the corner radius (in pixels) for the top right corner.
*
* @name cornerRadiusTopRight
* @memberof RectEncodingSet.prototype
* @type {(Value|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
*
* var encoding = new RectEncodingSet({
*     'cornerRadiusTopRight': new Value({
*         'value': 5
*     })
* });
*
* var v = encoding.cornerRadiusTopRight;
* // returns <Value>
*/
setReadWriteAccessor( RectEncodingSet.prototype, 'cornerRadiusTopRight', getCornerRadiusTopRight, setCornerRadiusTopRight );

/**
* EncodingSet properties.
*
* @name properties
* @memberof RectEncodingSet.prototype
* @type {Array<string>}
*
* @example
* var encoding = new RectEncodingSet();
*
* var v = encoding.properties;
* // returns [...]
*/
setNonEnumerableReadOnlyAccessor( RectEncodingSet.prototype, 'properties', getProperties );


// EXPORTS //

module.exports = RectEncodingSet;
